INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('96c4aca9-4b8a-43d8-bdf8-ae97b6968abb', 'この水道の水は、のんでも平気ですよ。', 'Air keran ini aman untuk diminum.') ON CONFLICT DO NOTHING;
